<script setup>
import {computed} from 'vue';
import {state,date} from '../store';
import Icon from './Icon.vue';
const props=defineProps({result:{required:true},previous:{default:null}});
const id=computed(()=>state.language==='id');
const scores=computed(()=>(props.result.competency_scores||[]).map(s=>({...s,percentage:Number(s.normalized_score??Number(s.score)/(props.result.score_max||100)*100)})).sort((a,b)=>a.percentage-b.percentage));
const strengths=computed(()=>scores.value.filter(score=>score.percentage>0).slice(-2).reverse());
const focus=computed(()=>props.result.recommendations?.length?props.result.recommendations.map(row=>({...row,percentage:Number(row.normalized_score)||0})):scores.value.slice(0,2));
const change=computed(()=>props.previous?Math.round(((props.result.normalized_score??Number(props.result.total_score)/(props.result.score_max||100)*100)-(props.previous.normalized_score??Number(props.previous.total_score)/(props.previous.score_max||100)*100))*10)/10:null);
const suggestions={
 grammar:['Latih imbuhan, kata depan, dan kalimat efektif. Tulis contoh baru dan periksa struktur setiap kalimat.','Practice affixes, prepositions, and effective sentences. Write new examples and check each sentence’s structure.'],
 reading:['Baca teks pendek, tandai gagasan utama, lalu buat ringkasan tanpa melihat kembali teks.','Read short texts, identify the main idea, and write a summary without looking back.'],
 listening:['Dengarkan percakapan singkat. Catat informasi penting, kemudian dengarkan ulang untuk memeriksa pemahaman.','Listen to short conversations, note key information, then listen again to check your understanding.'],
 vocabulary:['Pelajari kosakata dalam kalimat, bukan sebagai daftar terpisah. Gunakan kata baru dalam percakapan.','Learn vocabulary in sentences, then use new words in conversation.'],
 writing:['Buat kerangka sebelum menulis. Revisi hubungan antarparagraf, pilihan kata, dan kesesuaian dengan tugas.','Outline before writing. Revise paragraph connections, word choice, and how well the response answers the task.'],
 speaking:['Rekam jawaban singkat, dengarkan kembali, lalu ulangi dengan fokus pada kejelasan dan kelancaran.','Record short answers, listen back, and repeat with a focus on clarity and fluency.'],
 communication:['Latih dialog meminta informasi, menyampaikan pendapat, dan menanggapi secara sopan sesuai situasi.','Practice requesting information, expressing opinions, and responding politely in different situations.']
};
const label=s=>id.value?s.name:(s.name_en||s.name);
const advice=s=>(id.value?s.recommendation:s.recommendation_en)||s.recommendation||(suggestions[s.code]||['Latih kompetensi ini secara rutin dan tinjau umpan balik penilai untuk menentukan latihan berikutnya.','Practice this competency regularly and use your assessor’s feedback to choose your next exercise.'])[id.value?0:1];
</script>
<template>
<section v-if="result.level_recommendation" class="panel level-recommendation"><h3>{{id?'Rekomendasi pembelajaran':'Learning recommendation'}}</h3><p>{{result.level_recommendation}}</p></section><section class="result-insights">
<article class="panel insight-card"><span class="metric-icon cyan"><Icon name="Sparkles" :size="22"/></span><h3>{{id?'Kekuatan Anda':'Your strengths'}}</h3><template v-if="strengths.length"><div v-for="s in strengths" :key="s.competency_id" class="strength-item"><strong>{{label(s)}}</strong><span>{{s.percentage.toFixed(1)}}%</span></div><p>{{id?'Pertahankan keterampilan ini melalui penggunaan sehari-hari.':'Keep these skills active through everyday use.'}}</p></template><p v-else>{{id?'Hasil ini menjadi titik awal latihan Anda. Mulailah dari kompetensi yang paling membutuhkan perhatian.':'Use this result as your practice baseline. Start with the skills that need the most attention.'}}</p></article>
<article class="panel insight-card"><span class="metric-icon blue"><Icon name="Target" :size="22"/></span><h3>{{id?'Fokus latihan berikutnya':'Your next practice focus'}}</h3><div v-for="s in focus" :key="s.competency_id" class="practice-item"><strong>{{label(s)}} <small>{{s.percentage.toFixed(1)}}%</small></strong><p>{{advice(s)}}</p></div><small class="insight-note">{{id?'Saran berbasis skor kompetensi, bukan evaluasi AI.':'Suggestions are based on competency scores.'}}</small></article>
</section>
<section v-if="previous" class="panel comparison-card"><span class="metric-icon purple"><Icon name="TrendingUp" :size="23"/></span><div><h3>{{id?'Dibandingkan ujian sebelumnya':'Compared with your previous assessment'}}</h3><p>{{date(previous.submitted_at)}} · {{previous.total_score}} / {{previous.score_max}} → {{result.total_score}} / {{result.score_max}}</p><small>{{id?'Paket yang sama; perubahan versi materi dapat memengaruhi perbandingan.':'Same package; changes in assessment content may affect comparisons.'}}</small></div><strong :class="{positive:change>=0}">{{change>0?'+':''}}{{change}}<small>{{id?'poin persentase':'percentage points'}}</small></strong></section>
</template>
<style scoped>
.result-insights{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.3fr);gap:1.5rem;margin:1.5rem 0;align-items:stretch}.insight-card{padding:1.5rem;min-width:0;overflow-wrap:anywhere}.insight-card h3{font-size:1.375rem;line-height:1.45;margin:1rem 0}.insight-card p{font-size:1.125rem;line-height:1.8;color:var(--muted)}.strength-item{display:flex;align-items:baseline;justify-content:space-between;gap:1rem;padding:1rem 0;border-bottom:1px solid var(--border);font-size:1.125rem;line-height:1.6}.strength-item strong{min-width:0}.strength-item span{color:var(--color-accent);flex-shrink:0;font-variant-numeric:tabular-nums}.strength-item+p{margin-top:1rem}.practice-item{padding:1rem 0;border-bottom:1px solid var(--border)}.practice-item strong{display:flex;justify-content:space-between;align-items:baseline;gap:1rem;font-size:1.125rem;line-height:1.6}.practice-item strong small{color:var(--muted);font-weight:500;font-size:1rem;flex-shrink:0;font-variant-numeric:tabular-nums}.practice-item p{margin-top:.5rem;font-size:1.125rem}.insight-note{display:block;font-size:1rem;line-height:1.65;color:var(--muted);margin-top:1rem}.comparison-card{display:flex;align-items:flex-start;gap:1.5rem;padding:1.5rem;margin-bottom:1.5rem;min-width:0;flex-wrap:wrap}.comparison-card>div{flex:1 1 20rem;min-width:0;overflow-wrap:anywhere}.comparison-card h3{font-size:1.375rem;line-height:1.5}.comparison-card p{font-size:1.125rem;color:var(--muted);line-height:1.7;margin:.5rem 0}.comparison-card small{font-size:1rem;line-height:1.65;color:var(--muted)}.comparison-card>strong{margin-left:auto;font-size:2rem;color:var(--color-danger);text-align:right;flex:0 1 12rem;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.comparison-card>strong.positive{color:var(--color-accent)}.comparison-card>strong small{display:block;font-size:1rem;margin-top:.25rem;font-weight:400}.level-recommendation{overflow-wrap:anywhere}.level-recommendation h3{font-size:1.375rem;line-height:1.5}.level-recommendation p{font-size:1.125rem;line-height:1.8}@media(max-width:1000px){.result-insights{grid-template-columns:1fr}}@media(max-width:600px){.insight-card,.comparison-card{padding:1rem}.comparison-card{gap:1rem}.comparison-card>strong{flex-basis:100%;margin-left:0;text-align:left}.practice-item strong{flex-wrap:wrap;gap:.25rem .75rem}}
</style>
